# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>
#include <vector>

torch::Tensor mlp_forward(
    torch::Tensor x,
    std::vector<torch::Tensor> weights,
    std::vector<torch::Tensor> biases) {

    TORCH_CHECK(x.is_cuda() && x.dtype() == torch::kFloat32 && x.dim() == 2,
                "mlp_forward: x must be a 2D CUDA float32 tensor");
    TORCH_CHECK(weights.size() == biases.size() && weights.size() >= 1,
                "mlp_forward: weights and biases must be non-empty and same size");

    torch::Tensor out = x.contiguous();
    const int64_t num_layers = static_cast<int64_t>(weights.size());

    for (int64_t i = 0; i < num_layers; ++i) {
        auto& W = weights[i];
        auto& b = biases[i];
        TORCH_CHECK(W.is_cuda() && W.dtype() == torch::kFloat32 && W.dim() == 2,
                    "mlp_forward: weight[i] must be a 2D CUDA float32 tensor");
        TORCH_CHECK(b.is_cuda() && b.dtype() == torch::kFloat32 && b.dim() == 1,
                    "mlp_forward: bias[i] must be a 1D CUDA float32 tensor");
        TORCH_CHECK(W.size(1) == out.size(1),
                    "mlp_forward: weight input-dim mismatch at layer ", i);
        TORCH_CHECK(W.size(0) == b.size(0),
                    "mlp_forward: weight/bias output-dim mismatch at layer ", i);
        // out = out @ W^T + b  (matches nn.Linear semantics)
        out = at::addmm(b, out, W.t());
        // Apply ReLU on all layers except the last
        if (i < num_layers - 1) {
            out = at::relu(out);
        }
    }
    return out;
}

