    torch::NoGradGuard no_grad;
    torch::Tensor out = x.contiguous();

    for (int64_t i = 0; i < n_layers; ++i) {
        torch::Tensor w = weights[i].contiguous();
        torch::Tensor b = biases[i].contiguous();

        const int64_t M = out.size(0);
        const int64_t K = out.size(1);
        const int64_t N = w.size(0);

        torch::Tensor result = torch::empty({M, N}, torch::TensorOptions().dtype(torch::kFloat32).device(out.device()));

        cublasLtMatmulDesc_t matmulDesc;
        cublasLtMatrixLayout_t Adesc, Bdesc, Cdesc;
        cublasLtMatmulPreference_t preference;

        cublasOperation_t transa = CUBLAS_OP_N;
        cublasOperation_t transb = CUBLAS_OP_T;

