            torch::Tensor fallback_out = x;
            for (int64_t j = 0; j < n_layers; ++j) {
                fallback_out = torch::addmm(biases[j], fallback_out, weights[j].t());
                if (j < n_layers - 1) {
                    fallback_out = torch::relu_(fallback_out);
                }
            }
            return fallback_out;
        }

        cublasLtMatmulDescSetAttribute(matmulDesc, CUBLASLT_MATMUL_DESC_TRANSA, &transa, sizeof(transa));
        cublasLtMatmulDescSetAttribute(matmulDesc, CUBLASLT_MATMUL_DESC_TRANSB, &transb, sizeof(transb));

        if (i < n_layers - 1) {
            cublasLtEpilogue_t epilogue = CUBLASLT_EPILOGUE_RELU_BIAS;
            cublasLtMatmulDescSetAttribute(matmulDesc, CUBLASLT_MATMUL_DESC_EPILOGUE, &epilogue, sizeof(epilogue));
            cublasLtMatmulDescSetAttribute(matmulDesc, CUBLASLT_MATMUL_DESC_BIAS_POINTER, &(b.data_ptr<float>()), sizeof(float*));
